namespace Atc.Rest.Api.Generator.Cli.Extractors.TypeScript;

/// <summary>
/// Generates static error type files (ApiError.ts and ValidationError.ts).
/// </summary>
public static class TypeScriptErrorExtractor
{
    /// <summary>
    /// Generates the content for ApiError.ts.
    /// </summary>
    /// <param name="headerContent">Optional auto-generated file header.</param>
    /// <param name="httpClient">The HTTP client library to use.</param>
    /// <param name="hasWireNames">
    /// When true, the models rename keys: the constructor also takes the body as it came over the wire, which the
    /// ProblemDetails fields are read from while <c>body</c> holds the declared model under the models' names.
    /// </param>
    /// <returns>The TypeScript file content.</returns>
    public static string GenerateApiError(
        string? headerContent,
        TypeScriptHttpClient httpClient = TypeScriptHttpClient.Fetch,
        bool hasWireNames = false)
    {
        var sb = new StringBuilder();

        sb.Append(headerContent);

        var responseType = httpClient == TypeScriptHttpClient.Axios ? "AxiosResponse" : "Response";

        if (httpClient == TypeScriptHttpClient.Axios)
        {
            sb.AppendLine("import type { AxiosResponse } from 'axios';");
            sb.AppendLine();
        }

        sb.AppendLine("/**");
        sb.AppendLine(" * An error response.");
        sb.AppendLine(" *");
        sb.AppendLine(" * `body` is the parsed error body: an RFC 9457 ProblemDetails (what an API generated by");
        sb.AppendLine(" * Atc.Rest.Api.SourceGenerator returns), the error model the specification declares, or a string.");
        sb.AppendLine(" * When it is a ProblemDetails, its `type` / `title` / `detail` / `instance` are also available directly,");
        sb.AppendLine(" * and `message` is its `detail` (the server's message), falling back to `title`. A text body is the message");
        sb.AppendLine(" * only when it is short `text/plain` (see `errorMessage`); a proxy's HTML page stays in `body`.");
        sb.AppendLine(" */");
        sb.AppendLine("export class ApiError<TBody = unknown> extends Error {");
        sb.AppendLine("  readonly status: number;");
        sb.AppendLine("  readonly statusText: string;");
        sb.Append("  readonly response?: ").Append(responseType).AppendLine(";");
        sb.AppendLine("  readonly body?: TBody;");
        sb.AppendLine("  readonly type?: string;");
        sb.AppendLine("  readonly title?: string;");
        sb.AppendLine("  readonly detail?: string;");
        sb.AppendLine("  readonly instance?: string;");
        sb.AppendLine();
        if (hasWireNames)
        {
            sb.AppendLine("  /**");
            sb.AppendLine("   * @param body The error body; the declared error model under the models' property names.");
            sb.AppendLine("   * @param wireBody The body as it came over the wire (its ProblemDetails fields); defaults to `body`.");
            sb.AppendLine("   */");
            sb.Append("  constructor(status: number, statusText: string, message: string, response?: ").Append(responseType).AppendLine(", body?: TBody, wireBody: unknown = body) {");
        }
        else
        {
            sb.Append("  constructor(status: number, statusText: string, message: string, response?: ").Append(responseType).AppendLine(", body?: TBody) {");
        }

        var source = hasWireNames ? "wireBody" : "body";
        sb.AppendLine("    super(message);");
        sb.AppendLine("    this.name = 'ApiError';");
        sb.AppendLine("    this.status = status;");
        sb.AppendLine("    this.statusText = statusText;");
        sb.AppendLine("    this.response = response;");
        sb.AppendLine("    this.body = body;");
        sb.Append("    if (").Append(source).Append(" !== null && typeof ").Append(source).AppendLine(" === 'object') {");
        sb.Append("      const problem = ").Append(source).AppendLine(" as Record<string, unknown>;");
        sb.AppendLine("      this.type = typeof problem.type === 'string' ? problem.type : undefined;");
        sb.AppendLine("      this.title = typeof problem.title === 'string' ? problem.title : undefined;");
        sb.AppendLine("      this.detail = typeof problem.detail === 'string' ? problem.detail : undefined;");
        sb.AppendLine("      this.instance = typeof problem.instance === 'string' ? problem.instance : undefined;");
        sb.AppendLine("    }");
        sb.AppendLine("  }");
        sb.AppendLine("}");
        sb.AppendLine();
        sb.AppendLine("/** The longest text body used as the message; a longer one (a stack trace, a dump) stays in `body` only. */");
        sb.AppendLine("const MAX_MESSAGE_LENGTH = 200;");
        sb.AppendLine();
        sb.AppendLine("/**");
        sb.AppendLine(" * The message for an error response: a short `text/plain` body or JSON string, otherwise the ProblemDetails");
        sb.AppendLine(" * `detail`, `title` or a `message` property, otherwise the status text, otherwise `HTTP {status}`. A page - a");
        sb.AppendLine(" * proxy's HTML, a gateway's XML - or a long text is no message (it would land in a UI as is); it stays in `body`.");
        sb.AppendLine(" */");
        sb.AppendLine("export function errorMessage(status: number, statusText: string, body: unknown, contentType?: string | null): string {");
        sb.AppendLine("  if (typeof body === 'string') {");
        sb.AppendLine("    const type = ((contentType ?? '').split(';')[0] ?? '').trim().toLowerCase();");
        sb.AppendLine("    const text = body.trim();");
        sb.AppendLine("    const isText = type === '' || type === 'text/plain' || type === 'application/json' || type.endsWith('+json');");
        sb.AppendLine("    if (isText && text.length > 0 && text.length <= MAX_MESSAGE_LENGTH) {");
        sb.AppendLine("      return text;");
        sb.AppendLine("    }");
        sb.AppendLine("  }");
        sb.AppendLine();
        sb.AppendLine("  if (body !== null && typeof body === 'object') {");
        sb.AppendLine("    const problem = body as Record<string, unknown>;");
        sb.AppendLine("    for (const key of ['detail', 'title', 'message']) {");
        sb.AppendLine("      const value = problem[key];");
        sb.AppendLine("      if (typeof value === 'string' && value.length > 0) {");
        sb.AppendLine("        return value;");
        sb.AppendLine("      }");
        sb.AppendLine("    }");
        sb.AppendLine("  }");
        sb.AppendLine();
        sb.AppendLine("  return statusText.length > 0 ? statusText : `HTTP ${status}`;");
        sb.AppendLine("}");
        sb.AppendLine();
        sb.AppendLine("/**");
        sb.AppendLine(" * The text of a body: its bytes in the charset the `Content-Type` names - UTF-8 without one, or when the runtime");
        sb.AppendLine(" * does not know the name. (A response's own `text()` reads every body as UTF-8, whatever its charset.)");
        sb.AppendLine(" */");
        sb.AppendLine("export function decodeText(bytes: ArrayBuffer | ArrayBufferView, contentType?: string | null): string {");
        sb.AppendLine("  const charset = /;\\s*charset\\s*=\\s*\"?([^\";\\s]+)/i.exec(contentType ?? '')?.[1];");
        sb.AppendLine("  if (charset) {");
        sb.AppendLine("    try {");
        sb.AppendLine("      return new TextDecoder(charset).decode(bytes);");
        sb.AppendLine("    } catch {");
        sb.AppendLine("      // A charset the runtime does not know: read as UTF-8");
        sb.AppendLine("    }");
        sb.AppendLine("  }");
        sb.AppendLine();
        sb.AppendLine("  return new TextDecoder().decode(bytes);");
        sb.AppendLine("}");

        return sb.ToString();
    }

    /// <summary>
    /// Generates the content for ValidationError.ts.
    /// </summary>
    /// <param name="headerContent">Optional auto-generated file header.</param>
    /// <param name="httpClient">The HTTP client library to use.</param>
    /// <returns>The TypeScript file content.</returns>
    public static string GenerateValidationError(
        string? headerContent,
        TypeScriptHttpClient httpClient = TypeScriptHttpClient.Fetch,
        bool hasWireNames = false)
    {
        var sb = new StringBuilder();

        sb.Append(headerContent);

        var responseType = httpClient == TypeScriptHttpClient.Axios ? "AxiosResponse" : "Response";

        if (httpClient == TypeScriptHttpClient.Axios)
        {
            sb.AppendLine("import type { AxiosResponse } from 'axios';");
        }

        sb.AppendLine("import { ApiError } from './ApiError';");
        sb.AppendLine();
        sb.AppendLine("/**");
        sb.AppendLine(" * A 400 Bad Request. `errors` holds the validation errors keyed by the field names the client sent");
        sb.AppendLine(" * (empty when the response carries none).");
        sb.AppendLine(" */");
        sb.AppendLine("export class ValidationError<TBody = unknown> extends ApiError<TBody> {");
        sb.AppendLine("  readonly errors: Record<string, string[]>;");
        sb.AppendLine();
        sb.AppendLine("  constructor(");
        sb.AppendLine("    status: number,");
        sb.AppendLine("    statusText: string,");
        sb.AppendLine("    message: string,");
        sb.AppendLine("    errors: Record<string, string[]>,");
        sb.Append("    response?: ").Append(responseType).AppendLine(",");
        sb.AppendLine("    body?: TBody,");
        if (hasWireNames)
        {
            sb.AppendLine("    wireBody: unknown = body,");
            sb.AppendLine("  ) {");
            sb.AppendLine("    super(status, statusText, message, response, body, wireBody);");
        }
        else
        {
            sb.AppendLine("  ) {");
            sb.AppendLine("    super(status, statusText, message, response, body);");
        }

        sb.AppendLine("    this.name = 'ValidationError';");
        sb.AppendLine("    this.errors = errors;");
        sb.AppendLine("  }");
        sb.AppendLine("}");

        return sb.ToString();
    }
}